actions.script:
if (!ec.user.isInGroup('ADMIN') || System.getProperty('sales.qa.disposable') != 'true') {
    ec.web.response.setStatus(403); ec.web.sendJsonResponse([denied:true]); return
}
if (ec.entity.find('mantle.party.Party').condition('partyId','SALES_QA_A').disableAuthz().count() != 0) {
    ec.web.response.setStatus(409); ec.web.sendJsonResponse([denied:true]); return
}
ec.entity.makeDataLoader().location('component://zenith-erp-sales/SalesQaFixture.xml').load()
def demo=ec.entity.find('moqui.security.UserAccount').condition('userId','EX_JOHN_DOE').one()
def qa=ec.entity.find('moqui.security.UserAccount').condition('userId','SALES_QA_USER').one()
['currentPassword','passwordSalt','passwordHashType','passwordBase64'].each { qa.set(it,demo.get(it)) }
qa.disabled='N'; qa.requirePasswordChange='N'; qa.update()
def today=java.sql.Date.valueOf(ec.l10n.format(ec.user.nowTimestamp,'yyyy-MM-dd'))
['TODAY':today,'EXPIRED':new java.sql.Date(today.time-86400000L)].each { key,end ->
    ec.entity.find('zenith.erp.sales.WarrantyRegistration').condition('warrantyRegId','SALES_QA_WR_'+key).one().set('warrantyEndDate',end).update()
}
ec.entity.find('zenith.erp.sales.WarrantyRegistration').condition('warrantyRegId','SALES_QA_WR_FUTURE').one().set('warrantyStartDate',new java.sql.Date(today.time+86400000L)).update()
// InvoiceItem fixture import invokes Mantle's gross-total ECA and resets applied payments.
// Restore this exact synthetic partial-payment scenario after all fixture rows exist.
def cash=ec.entity.find('mantle.account.invoice.Invoice').condition('invoiceId','SALES_QA_CASH').one()
cash.invoiceTotal=900; cash.totalTaxableAmount=900; cash.totalTaxAmount=162
cash.totalCgst=81; cash.totalSgst=81; cash.totalIgst=0
cash.appliedPaymentsTotal=100; cash.unpaidTotal=800; cash.update()
ec.web.sendJsonResponse([initialized:true])

if (System.getProperty('sales.qa.disposable') != 'true' || ec.user.username != 'sales.qa') {
    ec.web.response.setStatus(403); ec.web.sendJsonResponse([denied:true]); return
}
def calls=[
    link:['zenith.sales.PaymentGatewayServices.create#PaymentLink',['invoiceId','gatewayType']],
    linkStatus:['zenith.sales.PaymentGatewayServices.check#PaymentStatus',['paymentLinkId']],
    callback:['zenith.sales.PaymentGatewayServices.process#PaymentCallback',['externalLinkId','status','transactionId']],
    upi:['zenith.sales.PaymentGatewayServices.generate#UpiPaymentQr',['invoiceId','upiId','merchantName']],
    invoice:['zenith.sales.SalesInvoiceServices.create#SalesInvoice',['organizationPartyId','customerPartyId','items','isReverseCharge']],
    claim:['zenith.sales.DeliveryChallanServices.file#WarrantyClaim',['warrantyRegId','issueDescription']],
    resolve:['zenith.sales.DeliveryChallanServices.resolve#WarrantyClaim',['warrantyClaimId','resolutionEnumId','serviceCost']],
    commission:['zenith.sales.CommissionServices.calculate#Commission',['orderId','partyId']],
    words:['zenith.india.GstServices.convert#AmountToIndianWords',['amount']],
    forecast:['zenith.sales.SalesForecastServices.forecast#Sales',['organizationPartyId']],
    serviceItem:['zenith.sales.SalesInvoiceServices.add#InvoiceItem',['invoiceId','productId','quantity','unitAmount','discountPercent']],
    register:['zenith.sales.DeliveryChallanServices.register#Warranty',['warrantyPolicyId','customerPartyId','productId','purchaseDate']]
]
def call=calls[ec.web.parameters.op]
if (!call) { ec.web.response.setStatus(400); ec.web.sendJsonResponse([denied:true]); return }
def params=[:]
call[1].each { name -> if(ec.web.parameters.containsKey(name)) params[name]=ec.web.parameters[name] }
if(params.items instanceof String) params.items=new groovy.json.JsonSlurper().parseText(params.items)
// Only the dedicated synthetic account can call this fixed service allowlist in this disposable JVM.
def result=ec.service.sync().name(call[0]).parameters(params).call()
def allowed=['invoiceId','paymentLinkId','paymentUrl','upiString','warrantyClaimId','warrantyRegId','commissionTxnId','commissionAmount','statusId','amountInWords','historyDays']
def publicResult=[:];allowed.each { if(result?.containsKey(it)) publicResult[it]=result[it] }
def errors=new ArrayList(ec.message.errors)
// Capture the rejection for the harness. The service has already marked its transaction
// rollback-only; clearing display errors does not authorize or commit a rejected write.
ec.message.clearErrors()
ec.web.sendJsonResponse([result:publicResult,errors:errors])
